import { createHash, randomBytes, timingSafeEqual, pbkdf2Sync } from 'crypto';
import { EventEmitter } from 'events';

interface ConnectionConfig {
  host: string;
  port: number;
  database: string;
  user: string;
  password?: string;
  authMethod?: 'password' | 'md5' | 'scram-sha-256';
}

interface AuthChallenge {
  method: string;
  salt: Buffer;
  iteration?: number;
}

class ConnectionPool extends EventEmitter {
  private connections: Map<string, AuthSession> = new Map();
  private config: ConnectionConfig;

  constructor(config: ConnectionConfig) {
    super();
    this.config = config;
  }

  private computeAuthDigest(password: string, salt: Buffer, method: string, iteration?: number): Buffer {
    if (method === 'md5') {
      const inner = createHash('md5')
        .update(password)
        .update(this.config.user)
        .digest();
      return createHash('md5')
        .update(inner)
        .update(salt)
        .digest();
    } else {
      // SCRAM-SHA-256 uses PBKDF2 key stretching with the server-provided
      // iteration count instead of a single unsalted-stretch hash.
      const iterations = iteration && iteration > 0 ? iteration : 4096;
      const key = pbkdf2Sync(password, salt, iterations, 32, 'sha256');
      return key;
    }
  }

  async authenticate(challenge: AuthChallenge): Promise<Buffer> {
    const digest = this.computeAuthDigest(
      this.config.password || '',
      challenge.salt,
      challenge.method,
      challenge.iteration
    );

    return digest;
  }

  async reconnect(sessionId: string): Promise<AuthSession> {
    const existing = this.connections.get(sessionId);
    if (existing && existing.isAuthenticated()) {
      return existing;
    }

    const session = new AuthSession(this.config, this);
    await session.connect();
    this.connections.set(sessionId, session);
    return session;
  }
}

